from kubernetes import client, config
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("k8s-rbac")
config.load_kube_config()


@mcp.tool()
def grant_namespace_role(namespace: str, role_name: str, subject_kind: str, subject_name: str) -> dict:
    subject = {"kind": subject_kind, "name": subject_name}
    if subject_kind == "ServiceAccount":
        subject["namespace"] = namespace
    else:
        subject["apiGroup"] = "rbac.authorization.k8s.io"
    body = {
        "apiVersion": "rbac.authorization.k8s.io/v1",
        "kind": "RoleBinding",
        "metadata": {"name": f"{role_name}-{subject_name}".lower()[:63], "namespace": namespace},
        "roleRef": {"apiGroup": "rbac.authorization.k8s.io", "kind": "Role", "name": role_name},
        "subjects": [subject],
    }
    with client.ApiClient() as api_client:
        rbac = client.RbacAuthorizationV1Api(api_client)
        created = rbac.create_namespaced_role_binding(namespace=namespace, body=body)
    return {"binding": created.metadata.name, "namespace": namespace, "role": role_name, "subject": subject_name}

import subprocess
from dataclasses import dataclass, asdict, field

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("k8s-nodes")


@dataclass
class NodeRemovalResult:
    node: str
    drained: bool = False
    deleted: bool = False
    evicted_pods: list = field(default_factory=list)
    error: str = ""


def _kubectl(args: list, timeout: int) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["kubectl", *args],
        capture_output=True,
        text=True,
        timeout=timeout,
    )


@mcp.tool()
def drain_and_remove_node(node_name: str, grace_period_seconds: int = 60, timeout_seconds: int = 600) -> dict:
    result = NodeRemovalResult(node=node_name)

    cordon = _kubectl(["cordon", node_name], 60)
    if cordon.returncode != 0:
        result.error = cordon.stderr.strip()
        return asdict(result)

    try:
        drain = _kubectl(
            [
                "drain",
                node_name,
                "--ignore-daemonsets",
                "--delete-emptydir-data",
                f"--grace-period={grace_period_seconds}",
                f"--timeout={timeout_seconds}s",
            ],
            timeout_seconds + 30,
        )
    except subprocess.TimeoutExpired:
        result.error = f"drain exceeded {timeout_seconds}s"
        return asdict(result)

    if drain.returncode != 0:
        result.error = drain.stderr.strip()
        return asdict(result)

    result.drained = True
    for line in drain.stdout.splitlines():
        if "evicted" in line:
            result.evicted_pods.append(line.split()[0].replace("pod/", ""))

    delete = _kubectl(["delete", "node", node_name, "--wait=true"], 120)
    if delete.returncode != 0:
        result.error = delete.stderr.strip()
        return asdict(result)

    result.deleted = True
    return asdict(result)

from kubernetes import client, config

config.load_kube_config()
_apps = client.AppsV1Api()


def _validated_replicas(replicas: int) -> int:
    if replicas < 0:
        raise ValueError("replicas must be zero or greater")
    return int(replicas)


def set_deployment_replicas(namespace: str, deployment: str, replicas: int) -> dict:
    count = _validated_replicas(replicas)
    current = _apps.read_namespaced_deployment_scale(name=deployment, namespace=namespace)
    previous = current.spec.replicas
    updated = _apps.patch_namespaced_deployment_scale(
        name=deployment,
        namespace=namespace,
        body={"spec": {"replicas": count}},
    )
    return {"deployment": deployment, "namespace": namespace, "previous": previous, "replicas": updated.spec.replicas}
